/**
 * Shared plumbing for the image / video / audio routes: request parsing,
 * budget + usage bookkeeping, and getting the generated bytes back to the
 * browser.
 */
import { assertBudget } from '@/lib/projects/server'
import { recordUsage, getCallerForLogging } from '@/lib/projects/usage'
import { uploadChatOutput } from '@/lib/storage/chat-outputs'
import { getCapability, type ModalityKind } from '@/lib/ai-capabilities'
import { describeGatewayError } from './server'

export interface MediaFile {
  name?: string
  contentType: string
  /** data: URL */
  url: string
}

export interface MediaRequest {
  prompt: string
  model?: string
  params: Record<string, unknown>
  files: MediaFile[]
  projectId: string | null
  chatId: string | null
}

export async function readMediaRequest(request: Request): Promise<MediaRequest | Response> {
  let body: Partial<MediaRequest> & { prompt?: unknown }
  try {
    body = await request.json()
  } catch {
    return Response.json({ success: false, error: 'Invalid request body' }, { status: 400 })
  }
  const prompt = typeof body.prompt === 'string' ? body.prompt.trim() : ''
  const files = Array.isArray(body.files)
    ? body.files.filter(f => f && typeof f.url === 'string' && f.url.startsWith('data:')).slice(0, 8)
    : []
  return {
    prompt,
    model: typeof body.model === 'string' ? body.model : undefined,
    params: body.params && typeof body.params === 'object' ? body.params : {},
    files,
    projectId: body.projectId ?? null,
    chatId: typeof body.chatId === 'string' ? body.chatId : null,
  }
}

/** Budget gate. Returns a Response to send back when the project is out of credit. */
export async function checkBudget(projectId: string | null) {
  const caller = await getCallerForLogging()
  if (projectId && caller) {
    try {
      await assertBudget({ projectId, userId: caller.userId })
    } catch (e) {
      const err = e as Error & { status?: number }
      return { caller, blocked: Response.json({ success: false, error: err.message }, { status: err.status ?? 402 }) }
    }
  }
  return { caller, blocked: null as Response | null }
}

export function logUsage(
  caller: Awaited<ReturnType<typeof getCallerForLogging>>,
  entry: { provider: string; model: string; modality: 'image' | 'video' | 'audio'; count: number; projectId: string | null; chatId: string | null },
) {
  if (!caller) return
  for (let i = 0; i < entry.count; i++) {
    void recordUsage({
      userId: caller.userId,
      domain: caller.domain,
      provider: entry.provider,
      model: entry.model,
      modality: entry.modality,
      chatType: entry.modality,
      projectId: entry.projectId,
      chatId: entry.chatId,
    })
  }
}

/** data: URL → bytes + media type. */
export function decodeDataUrl(url: string): { bytes: Uint8Array; mediaType: string } {
  const m = url.match(/^data:([^;,]+)?(;base64)?,([\s\S]*)$/)
  if (!m) throw new Error('Attachment is not a data URL')
  const mediaType = m[1] || 'application/octet-stream'
  const bytes = m[2] ? Buffer.from(m[3], 'base64') : Buffer.from(decodeURIComponent(m[3]))
  return { bytes: new Uint8Array(bytes), mediaType }
}

const EXT: Record<string, string> = {
  'image/png': 'png', 'image/jpeg': 'jpg', 'image/webp': 'webp', 'image/svg+xml': 'svg',
  'video/mp4': 'mp4', 'video/webm': 'webm', 'video/quicktime': 'mov',
  'audio/mpeg': 'mp3', 'audio/mp3': 'mp3', 'audio/wav': 'wav', 'audio/ogg': 'ogg',
  'audio/flac': 'flac', 'audio/aac': 'aac', 'audio/opus': 'opus',
}

/** Vercel caps function responses at 4.5 MB; stay comfortably under it. */
const INLINE_LIMIT_BYTES = 3 * 1024 * 1024

/**
 * Returns browser-usable URLs for generated media. Small results come back
 * inline as data URLs; anything that would push the response past the
 * function size limit is stored in the `chat-outputs` bucket and returned
 * as a signed URL.
 */
export async function deliver(
  outputs: Array<{ bytes: Uint8Array; mediaType: string }>,
  ctx: { caller: Awaited<ReturnType<typeof getCallerForLogging>>; chatId: string | null; kind: string },
): Promise<string[]> {
  const total = outputs.reduce((n, o) => n + o.bytes.byteLength, 0)
  if (total <= INLINE_LIMIT_BYTES || !ctx.caller) {
    if (total > INLINE_LIMIT_BYTES) {
      throw new Error('The generated file is too large to return without a signed-in account to store it.')
    }
    return outputs.map(o => `data:${o.mediaType};base64,${Buffer.from(o.bytes).toString('base64')}`)
  }
  const stamp = Date.now()
  return Promise.all(
    outputs.map(async (o, i) => {
      const ext = EXT[o.mediaType] ?? o.mediaType.split('/')[1] ?? 'bin'
      const uploaded = await uploadChatOutput({
        userId: ctx.caller!.userId,
        chatId: ctx.chatId ?? 'media',
        filename: `${ctx.kind}-${stamp}-${i + 1}.${ext}`,
        content: Buffer.from(o.bytes),
        contentType: o.mediaType,
      })
      return uploaded.signedUrl
    }),
  )
}

const MAX_DOWNLOAD_BYTES = 500 * 1024 * 1024

/**
 * Fetches a finished video from the provider's URL. The SDK's default
 * downloader (an SSRF-guarded node fetch) can't resolve its own module path
 * once Next bundles it, so the route supplies this plain HTTPS fetch.
 */
export async function downloadMedia({ url, abortSignal }: { url: URL; abortSignal?: AbortSignal }) {
  if (url.protocol !== 'https:') throw new Error(`Refusing to download ${url.protocol} media`)
  const res = await fetch(url, { signal: abortSignal })
  if (!res.ok) throw new Error(`Could not download the result (${res.status})`)
  const size = Number(res.headers.get('content-length') ?? 0)
  if (size > MAX_DOWNLOAD_BYTES) throw new Error('The result is too large to download')
  const data = new Uint8Array(await res.arrayBuffer())
  if (data.byteLength > MAX_DOWNLOAD_BYTES) throw new Error('The result is too large to download')
  return { data, mediaType: res.headers.get('content-type')?.split(';')[0] ?? undefined }
}

/** Stores input images and returns signed URLs a provider can fetch. */
export async function hostInputs(
  images: Array<{ bytes: Uint8Array; mediaType: string }>,
  ctx: { caller: NonNullable<Awaited<ReturnType<typeof getCallerForLogging>>>; chatId: string | null },
): Promise<string[]> {
  const stamp = Date.now()
  return Promise.all(
    images.map(async (img, i) => {
      const ext = EXT[img.mediaType] ?? 'png'
      const uploaded = await uploadChatOutput({
        userId: ctx.caller.userId,
        chatId: ctx.chatId ?? 'media',
        filename: `input-${stamp}-${i + 1}.${ext}`,
        content: Buffer.from(img.bytes),
        contentType: img.mediaType,
      })
      return uploaded.signedUrl
    }),
  )
}

/** SDK warnings → short human strings ("seed is not supported", …). */
export function warningText(warnings: unknown): string[] {
  if (!Array.isArray(warnings)) return []
  return warnings
    .map(w => {
      const x = w as { type?: string; feature?: string; setting?: string; details?: string; message?: string }
      if (x.details) return x.details
      if (x.message) return x.message
      const what = x.feature ?? x.setting
      return what ? `${what} is not supported by this model` : ''
    })
    .filter(Boolean)
}

export function errorResponse(error: unknown, label: string) {
  const { message, status } = describeGatewayError(error)
  console.error(`[v0] ${label} error:`, message)
  return Response.json({ success: false, error: message }, { status })
}

/**
 * The config pane shows each field's default but only sends what the user
 * changed. Fill in the defaults the pane displayed and drop keys the model
 * doesn't have, so the request matches what's on screen.
 */
export function withDefaults(
  params: Record<string, unknown>,
  modelId: string,
  kind: ModalityKind,
): Record<string, unknown> {
  const fields = getCapability(modelId, kind)?.fields
  if (!fields) return params
  const out: Record<string, unknown> = {}
  for (const [key, field] of Object.entries(fields)) {
    const value = params[key] !== undefined ? params[key] : (field as { default?: unknown }).default
    if (value !== undefined) out[key] = value
  }
  return out
}

export function seedFrom(v: unknown): number | undefined {
  if (v === undefined || v === null || v === '') return undefined
  const n = Number(v)
  return Number.isFinite(n) ? Math.floor(n) : undefined
}
